// Spring·Persistence·Network 담당 초안. 최종 출제 파일로 직접 가져가지 않는다.
// 모든 evidence는 각 sourceId의 고정 로컬 Markdown에서 대조한 문자열이다.
const COMMIT = 'd00877afb0a302072078d34ded66b3b69143a5ca';

function wrongChoices(answer, sourceId, kind) {
  // 공통 메타 문구가 정답 단서가 되지 않도록, 각 문항의 실제 정답 문장을
  // 바탕으로 서로 다른 오해(적용 범위·처리 시점·책임 주체)를 만든다.
  const subject = answer.replace(/(이다|된다|한다|있다|없다|사용한다|의미한다|제공한다|발생한다|가능하다|필요하다|생긴다|동작한다|저장된다|관리한다|처리한다|수행한다|보장한다|결정한다)\.$/, '');
  const variants = [
    `${subject}는 모든 상황에서 예외 없이 동일하게 적용된다.`,
    `${subject}는 요청 처리와 무관하게 클라이언트만 책임진다.`,
    `${subject}는 별도 조건 없이 항상 즉시 완료된다.`,
    `${subject}는 서버와 데이터 저장소의 상태에 영향을 주지 않는다.`,
    `${subject}는 설정이나 호출 경로와 관계없이 자동으로 비활성화된다.`,
    `${subject}는 다른 계층의 기능으로 대체되어 확인할 필요가 없다.`,
  ];
  const offset = [...sourceId].reduce((sum, char) => sum + char.charCodeAt(0), kind === 'follow-up' ? 3 : 0) % variants.length;
  return Object.freeze([variants[offset], variants[(offset + 2) % variants.length], variants[(offset + 4) % variants.length]]);
}

function pair({ sourceId, categoryId, main, follow }) {
  const mainId = `quiz-${sourceId}-main`;
  const base = {
    version: 1,
    categoryId,
    sourceId,
    sourceCommit: COMMIT,
    sourceHeading: '본문',
    reviewStatus: 'verified',
    provenance: Object.freeze({ author: 'codex-curated', review: 'pending-independent-audit' }),
  };
  return Object.freeze([
    Object.freeze({
      ...base, id: mainId, kind: 'main', followUpOf: null,
      question: `${sourceId} 원문의 설명과 일치하는 것은 무엇인가요?`,
      choices: Object.freeze([main.answer, ...(main.wrong ?? wrongChoices(main.answer, sourceId, 'main'))]), correctIndex: 0,
      explanation: `원문은 ${main.answer}라고 설명합니다.`, evidenceQuote: main.quote,
    }),
    Object.freeze({
      ...base, id: `quiz-${sourceId}-follow-up`, kind: 'follow-up', followUpOf: mainId,
      question: `${sourceId}의 조건·영향을 판단할 때 원문 근거로 가장 적절한 설명은 무엇인가요?`,
      choices: Object.freeze([follow.answer, ...(follow.wrong ?? wrongChoices(follow.answer, sourceId, 'follow-up'))]), correctIndex: 0,
      explanation: `원문 근거는 ${follow.answer}입니다.`, evidenceQuote: follow.quote,
    }),
  ]);
}

